import { Alert, Button, Checkbox, Field, FieldDescription, FieldError, FieldLabel, Input, Link, PasswordInput, cn } from '@gntik-ai/ui';
import { Lock, Mail } from '@gntik-ai/icons';
import { useImperativeHandle, useRef, useState, type MouseEvent, type ReactNode, type Ref } from 'react';
import { SsoButtons } from '../sso-buttons/SsoButtons';
import {
  AuthDivider,
  AuthHeader,
  authIdentifierError,
  authFormClass,
  useAsyncSubmit,
  type AuthIdentifierConfig,
  type AuthValidationMessages,
  type AuthFormAccessibilityProps,
  type AuthHeaderProps,
} from '../shared';

export interface SignInValues {
  email: string;
  /** Trimmed identifier in text mode. `email` remains available for existing consumers. */
  identifier?: string;
  password: string;
  remember: boolean;
}

export interface SignInFormRef {
  focus(field: 'identifier' | 'password'): void;
}

export interface SignInFormProps extends AuthFormAccessibilityProps {
  /** React 19 ref for focus after a server response. */
  ref?: Ref<SignInFormRef>;
  identifier?: AuthIdentifierConfig;
  /** The kit validates before submit. Supply copy here; do not add a second inline validator. */
  messages?: AuthValidationMessages;
  passwordHelp?: ReactNode;
  passwordHelpId?: string;
  /** Signs in. A returned promise shows the loading state; a rejection's message shows in the alert. */
  onSubmit?: (values: SignInValues) => void | Promise<void>;
  /** Error from the server (e.g. "Incorrect email or password"). */
  error?: string | null;
  /** Forces the loading state (when the parent tracks the request). */
  loading?: boolean;
  defaultEmail?: string;
  forgotPasswordHref?: string;
  onForgotPassword?: () => void;
  signUpHref?: string;
  onSignUp?: () => void;
  /** Replaces the sign-up prompt; `null` hides it. Defaults to the existing account link. */
  signUpPrompt?: ReactNode;
  /** SSO area under the divider; defaults to SsoButtons, `null` hides it. */
  sso?: ReactNode;
  eyebrow?: ReactNode;
  title?: ReactNode;
  description?: ReactNode;
  /** Omit the internal heading with null; the form keeps its accessible name. */
  headingLevel?: AuthHeaderProps['headingLevel'];
  className?: string;
}

const linkHandler = (fn?: () => void) =>
  fn
    ? (e: MouseEvent) => {
        e.preventDefault();
        fn();
      }
    : undefined;

/** Email + password sign-in with remember me, forgot-password link, SSO slot, error alert and loading. */
export function SignInForm({
  identifier,
  messages,
  passwordHelp,
  passwordHelpId,
  ref,
  fieldInvalid,
  feedbackId,
  'aria-describedby': describedBy,
  'aria-label': ariaLabel = 'Sign in',
  'aria-labelledby': labelledBy,
  onSubmit,
  error: errorProp,
  loading: loadingProp,
  defaultEmail = '',
  forgotPasswordHref = '#',
  onForgotPassword,
  signUpHref = '#',
  onSignUp,
  signUpPrompt,
  sso = <SsoButtons />,
  eyebrow = 'Secure access',
  title = 'Sign in to your workspace',
  description = 'Use your work email to continue.',
  headingLevel,
  className,
}: SignInFormProps) {
  const [email, setEmail] = useState(defaultEmail);
  const [password, setPassword] = useState('');
  const [remember, setRemember] = useState(true);
  const [submitted, setSubmitted] = useState(false);
  const { loading, error, run } = useAsyncSubmit('Sign-in failed. Try again.');
  const busy = loadingProp ?? loading;
  const alert = errorProp ?? error;
  const identifierInput = useRef<HTMLInputElement>(null);
  const passwordInput = useRef<HTMLInputElement>(null);
  useImperativeHandle(
    ref,
    () => ({
      focus: (field) => (field === 'password' ? passwordInput : identifierInput).current?.focus(),
    }),
    [],
  );
  const identifierError = authIdentifierError(email, identifier, messages);
  const emailInvalid = submitted && identifierError !== null;
  const passwordInvalid = submitted && password === '';

  return (
    <div className={cn(authFormClass, className)}>
      <AuthHeader eyebrow={eyebrow} title={title} description={description} headingLevel={headingLevel} />
      <form
        noValidate
        aria-label={ariaLabel}
        aria-labelledby={labelledBy}
        aria-describedby={describedBy}
        className="flex flex-col gap-4"
        onSubmit={(e) => {
          e.preventDefault();
          setSubmitted(true);
          if (identifierError !== null) {
            identifierInput.current?.focus();
            return;
          }
          if (password === '') {
            passwordInput.current?.focus();
            return;
          }
          void run(() => onSubmit?.({ email: email.trim(), ...(identifier?.type === 'text' ? { identifier: email.trim() } : {}), password, remember }));
        }}
      >
        {alert && <Alert id={feedbackId} tone="destructive" description={alert} />}
        <Field invalid={emailInvalid || fieldInvalid?.identifier === true}>
          <FieldLabel>{identifier?.label ?? 'Email'}</FieldLabel>
          <Input
            ref={identifierInput}
            aria-describedby={fieldInvalid?.identifier ? feedbackId : undefined}
            type={identifier?.type ?? 'email'}
            leadingIcon={Mail}
            autoComplete={identifier?.autoComplete ?? 'email'}
            placeholder={identifier?.placeholder ?? 'name@company.com'}
            minLength={identifier?.minLength}
            maxLength={identifier?.maxLength}
            value={email}
            onValueChange={setEmail}
            required
          />
          {identifier?.help != null && <FieldDescription id={identifier.helpId}>{identifier.help}</FieldDescription>}
          <FieldError role="alert" match={emailInvalid}>
            {identifierError}
          </FieldError>
        </Field>
        <Field invalid={passwordInvalid || fieldInvalid?.password === true}>
          <div className="flex items-center justify-between gap-3">
            <FieldLabel>Password</FieldLabel>
            <Link href={forgotPasswordHref} onClick={linkHandler(onForgotPassword)} className="text-[12.5px]">
              Forgot password?
            </Link>
          </div>
          <PasswordInput
            ref={passwordInput}
            aria-describedby={fieldInvalid?.password ? feedbackId : undefined}
            leadingIcon={Lock}
            value={password}
            onValueChange={setPassword}
            required
          />
          {passwordHelp != null && <FieldDescription id={passwordHelpId}>{passwordHelp}</FieldDescription>}
          <FieldError role="alert" match={passwordInvalid}>
            {messages?.passwordRequired ?? 'Enter your password.'}
          </FieldError>
        </Field>
        <Checkbox label="Keep me signed in" checked={remember} onCheckedChange={setRemember} />
        <Button type="submit" size="lg" loading={busy} className="mt-2 w-full">
          Sign in
        </Button>
      </form>
      {sso != null && (
        <>
          <AuthDivider>Or continue with</AuthDivider>
          {sso}
        </>
      )}
      {signUpPrompt !== null && (
        <p className="mt-7 text-center text-[13px] text-muted-foreground">
          {signUpPrompt === undefined ? (
            <>
              New here?{' '}
              <Link href={signUpHref} onClick={linkHandler(onSignUp)}>
                Create an account
              </Link>
            </>
          ) : (
            signUpPrompt
          )}
        </p>
      )}
    </div>
  );
}

import { cn } from '@gntik-ai/ui';
import { useState, type ReactNode } from 'react';

export interface AuthHeaderProps {
  eyebrow?: ReactNode;
  title: ReactNode;
  description?: ReactNode;
  /** Defaults to h1. `null` omits the title heading. */
  headingLevel?: 'h1' | 'h2' | 'h3' | null;
  className?: string;
}

/** Eyebrow + title + supporting line used at the top of every auth form. */
export function AuthHeader({ eyebrow, title, description, headingLevel: Heading = 'h1', className }: AuthHeaderProps) {
  return (
    <div className={cn('mb-6', className)}>
      {eyebrow != null && <p className="mb-2.5 font-mono text-[11px] tracking-[0.2em] text-primary-text uppercase">{eyebrow}</p>}
      {Heading != null && title != null && <Heading className="text-[24px] font-semibold tracking-tight text-balance text-foreground sm:text-[27px]">{title}</Heading>}
      {description != null && <p className="mt-2 text-[14px] leading-relaxed text-pretty text-muted-foreground">{description}</p>}
    </div>
  );
}

/** Horizontal rule with a centred caption ("Or continue with"). */
export function AuthDivider({ children }: { children: ReactNode }) {
  return (
    <div className="my-6 flex items-center gap-3" role="presentation">
      <span className="h-px flex-1 bg-border" />
      <span className="font-mono text-[10.5px] font-semibold tracking-[0.2em] text-muted-foreground uppercase">{children}</span>
      <span className="h-px flex-1 bg-border" />
    </div>
  );
}

export const authFormClass = 'w-full max-w-[392px]';

/** Loading + error state around an async submit handler. A rejection's message becomes the error. */
export function useAsyncSubmit(fallbackError = 'Something went wrong. Try again.') {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const run = async (fn: () => void | Promise<void>) => {
    setError(null);
    setLoading(true);
    try {
      await fn();
      setLoading(false);
      return true;
    } catch (e) {
      setLoading(false);
      setError(e instanceof Error ? e.message : fallbackError);
      return false;
    }
  };
  return { loading, error, setError, run };
}

export const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** Email by default; text mode supports a username or username-or-email identifier. */
export interface AuthIdentifierConfig {
  type?: 'email' | 'text';
  autoComplete?: string;
  label?: ReactNode;
  help?: ReactNode;
  /** Optional stable id for the FieldDescription. Otherwise Base UI generates it. */
  helpId?: string;
  placeholder?: string;
  minLength?: number;
  maxLength?: number;
}

/** Kit-owned inline validation; consumers supply copy rather than running a second validator. */
export interface AuthValidationMessages {
  identifierRequired?: string;
  identifierInvalid?: string;
  identifierTooShort?: string;
  passwordRequired?: string;
}

/** Server errors use only these props plus the form's error alert; inline validation stays in the kit. */
export interface AuthFormAccessibilityProps {
  fieldInvalid?: { identifier?: boolean; password?: boolean };
  /** Id of the server alert (or an external feedback element), appended to flagged inputs. */
  feedbackId?: string;
  /** Describes the form itself; does not replace the per-field feedback association. */
  'aria-describedby'?: string;
  'aria-label'?: string;
  'aria-labelledby'?: string;
}

export function authIdentifierError(value: string, config?: AuthIdentifierConfig, messages?: AuthValidationMessages) {
  const trimmed = value.trim();
  const fallback = config?.type === 'text' ? 'Enter a valid identifier.' : 'Enter a valid email address.';
  if (!trimmed) return messages?.identifierRequired ?? fallback;
  if (config?.minLength !== undefined && trimmed.length < config.minLength) return messages?.identifierTooShort ?? messages?.identifierInvalid ?? fallback;
  if (((config?.type ?? 'email') === 'email' && !EMAIL_RE.test(trimmed)) || (config?.maxLength !== undefined && trimmed.length > config.maxLength))
    return messages?.identifierInvalid ?? fallback;
  return null;
}
